import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l1_p26_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor gelu_cuda(torch::Tensor x);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("gelu_cuda", &gelu_cuda, "GELU CUDA (float4 vectorized)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void gelu_float4_kernel(const float* __restrict__ input,
                                    float* __restrict__ output,
                                    int64_t n4) {
    const float kAlpha = 0.70710678118654752440f;
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
    int64_t stride = (int64_t)gridDim.x * blockDim.x;
    const float4* in4 = reinterpret_cast<const float4*>(input);
    float4* out4 = reinterpret_cast<float4*>(output);
    for (int64_t i = idx; i < n4; i += stride) {
        float4 v = __ldg(in4 + i);
        v.x = 0.5f * v.x * (1.0f + erff(v.x * kAlpha));
        v.y = 0.5f * v.y * (1.0f + erff(v.y * kAlpha));
        v.z = 0.5f * v.z * (1.0f + erff(v.z * kAlpha));
        v.w = 0.5f * v.w * (1.0f + erff(v.w * kAlpha));
        out4[i] = v;
    }
}

__global__ void gelu_scalar_kernel(const float* __restrict__ input,
                                    float* __restrict__ output,
                                    int64_t offset, int64_t n) {
    const float kAlpha = 0.70710678118654752440f;
    int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x + offset;
    if (idx < n) {
        float x = input[idx];
        output[idx] = 0.5f * x * (1.0f + erff(x * kAlpha));
    }
}

torch::Tensor gelu_cuda(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "Input must be a CUDA tensor");
    TORCH_CHECK(x.is_contiguous(), "Input must be contiguous");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "Input must be float32");
    auto output = torch::empty_like(x);
    int64_t n = x.numel();
    int64_t n4 = n / 4;
    int64_t tail = n % 4;
    const int threads = 256;
    if (n4 > 0) {
        int blocks = (int)min((n4 + threads - 1) / threads, (int64_t)65535);
        gelu_float4_kernel<<<blocks, threads>>>(
            x.data_ptr<float>(), output.data_ptr<float>(), n4);
    }
    if (tail > 0) {
        int64_t offset = n4 * 4;
        gelu_scalar_kernel<<<1, (int)tail>>>(
            x.data_ptr<float>(), output.data_ptr<float>(), offset, n);
    }
    return output;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Simple model that performs a GELU activation.
        """
    def __init__(self):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        # <<<END_IMPROVE>>>

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # <<<IMPROVE:forward_stmt_1>>>
        if x.is_cuda and x.is_contiguous() and x.dtype == torch.float32:
                    return _stark_get_extension().gelu_cuda(x)
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        return torch.nn.functional.gelu(x)
        # <<<END_IMPROVE>>>

